const $in = $input.first().json;

const h = $in.headers || {};
const ip = String(h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || 'unknown').trim();
const store = $getWorkflowStaticData('global');
const now = Date.now();
store.hits = Object.fromEntries(Object.entries(store.hits || {}).map(([k, v]) => [k, v.filter(t => now - t < 3600e3)]).filter(([, v]) => v.length));
const mine = store.hits[ip] || [];
if (mine.length >= 3000) return [{ json: { ok: false, status: 429, body: { success: false, message: 'Too many attempts from this network. Please try again in an hour.' } } }];
const count = () => { store.hits[ip] = [...mine, now]; };

// Automatic refreshes share one copy for 5 seconds so a crowd watching doesn't each hit the database.
// A page load or manual refresh sends fresh=1 and always reads the latest score (still rate limited).
const cache = $getWorkflowStaticData('global');
const key = 's:' + String(($in.query || {}).slug || '');
const hit = (cache.c || {})[key];
if (hit && Date.now() - hit.at < 5000 && String(($in.query || {}).fresh || '') !== '1') return [{ json: { ok: false, status: 200, body: hit.body } }];

const q = $in.query || {};
const slug = String(q.slug || '').toLowerCase();
if (!/^[a-z0-9-]{2,40}$/.test(slug)) return [{ json: { ok: false, status: 404, body: { success: false, message: 'This page does not exist.' } } }];
count();
// No login: the viewer is nobody, so only published fixtures are shown.
return [{ json: { ok: true, phone: '', code: slug, slug, _q: { slug } } }];

const $in = $input.first().json;
if (!$in.id) return [{ json: { ok: false, status: 404, body: { success: false, message: "Tournament not found." } } }];
return [{ json: { ok: true, ...$in } }];

// Fresh saved B2 links (add_b2_cache.py): skip the B2 calls.
const saved = $getWorkflowStaticData('global').b2;
const b2Fresh = !!(saved && Date.now() - saved.at < 20 * 3600e3 && ["Team Link"].every(n => saved.links && saved.links[n]));
return [{ json: { basicAuth: 'Basic ' + Buffer.from(`${$env.B2_KEY_ID}:${$env.B2_APPLICATION_KEY}`).toString('base64'), b2Fresh } }];

const __b2 = $('B2 Ready').first().json; // B2 links, saved or fresh (add_b2_cache.py)
const __$ = n => n === 'Authorize B2' || __b2.links[n] ? (j => ({ isExecuted: true, first: () => ({ json: j }), all: () => [{ json: j }] }))(n === 'Authorize B2' ? __b2.acct : __b2.links[n]) : $(n);

const b2 = __$('Authorize B2').isExecuted ? __$('Authorize B2').first().json : {};
const dl = b2?.apiInfo?.storageApi?.downloadUrl;
const tokenOf = node => { try { return __$(node).isExecuted ? __$(node).first().json.authorizationToken : null; } catch { return null; } };
const signWith = (key, node) => { const t = tokenOf(node); return key && dl && t ? `${dl}/file/mypaltan-profile-photos/${key.split('/').map(encodeURIComponent).join('/')}?Authorization=${t}` : null; };
const parseJ = v => { if (v === null || v === undefined) return null; if (typeof v === 'object') return v; try { return JSON.parse(v); } catch { return null; } };
// ── Tournament player stats from scored matches (embedded in n8n; also unit-tested in node) ──
// matches: [{ division_id, innings: [{ batting_entry_id, bowling_entry_id, batting: [card], bowling: [card] }] }]
// Batting card: {id, name, runs, balls, fours, sixes, out}. Bowling card: {id, name, legal_balls, runs, wickets, maidens, dots}.
function computeStats(matches) {
  const players = new Map(); // `${division}:${memberId}` → totals
  const get = (div, id, name, entry) => {
    const k = `${div}:${id}`;
    if (!players.has(k)) players.set(k, { division_id: div, member_id: id, name, entry_id: entry, matches: new Set(),
      innings: 0, runs: 0, balls: 0, fours: 0, sixes: 0, outs: 0, high: 0, high_not_out: false, fifties: 0,
      bowl_innings: 0, legal_balls: 0, runs_conceded: 0, wickets: 0, maidens: 0, dots: 0, best_w: -1, best_r: 0 });
    return players.get(k);
  };
  matches.forEach((m, mi) => {
    for (const inn of m.innings || []) {
      for (const b of inn.batting || []) {
        const p = get(m.division_id, b.id, b.name, inn.batting_entry_id);
        p.matches.add(mi);
        p.innings++; p.runs += b.runs; p.balls += b.balls; p.fours += b.fours; p.sixes += b.sixes;
        if (b.out) p.outs++;
        if (b.runs > p.high || (b.runs === p.high && !b.out)) { p.high = b.runs; p.high_not_out = !b.out; }
        if (b.runs >= 50) p.fifties++;
      }
      for (const b of inn.bowling || []) {
        const p = get(m.division_id, b.id, b.name, inn.bowling_entry_id);
        p.matches.add(mi);
        p.bowl_innings++; p.legal_balls += b.legal_balls; p.runs_conceded += b.runs; p.wickets += b.wickets;
        p.maidens += b.maidens || 0; p.dots += b.dots || 0;
        if (b.wickets > p.best_w || (b.wickets === p.best_w && b.runs < p.best_r)) { p.best_w = b.wickets; p.best_r = b.runs; }
      }
    }
  });
  const r2 = v => Math.round(v * 100) / 100;
  return [...players.values()].map(p => ({
    division_id: p.division_id, member_id: p.member_id, name: p.name, entry_id: p.entry_id, matches: p.matches.size,
    innings: p.innings, runs: p.runs, balls: p.balls, fours: p.fours, sixes: p.sixes, outs: p.outs,
    highest: p.innings ? `${p.high}${p.high_not_out ? '*' : ''}` : null, highest_runs: p.high, fifties: p.fifties,
    average: p.outs ? r2(p.runs / p.outs) : null, strike_rate: p.balls ? r2(p.runs * 100 / p.balls) : null,
    overs: `${Math.floor(p.legal_balls / 6)}.${p.legal_balls % 6}`, legal_balls: p.legal_balls, runs_conceded: p.runs_conceded,
    wickets: p.wickets, maidens: p.maidens, dots: p.dots, economy: p.legal_balls ? r2(p.runs_conceded * 6 / p.legal_balls) : null,
    best: p.best_w >= 0 ? `${p.best_w}/${p.best_r}` : null, best_wickets: Math.max(0, p.best_w), best_runs: p.best_r,
  }));
}

/** Top players per category for one division. */
function leaderboards(rows, top = 10) {
  const take = (filter, sort) => rows.filter(filter).sort(sort).slice(0, top);
  return {
    most_runs: take(p => p.runs > 0, (a, b) => b.runs - a.runs || (b.strike_rate || 0) - (a.strike_rate || 0)),
    most_wickets: take(p => p.wickets > 0, (a, b) => b.wickets - a.wickets || (a.economy ?? 99) - (b.economy ?? 99)),
    highest_score: take(p => p.innings > 0 && p.highest_runs > 0, (a, b) => b.highest_runs - a.highest_runs),
    best_bowling: take(p => p.best_wickets > 0, (a, b) => b.best_wickets - a.best_wickets || a.best_runs - b.best_runs),
    most_sixes: take(p => p.sixes > 0, (a, b) => b.sixes - a.sixes),
    best_strike_rate: take(p => p.balls >= 10, (a, b) => b.strike_rate - a.strike_rate),
    best_economy: take(p => p.legal_balls >= 12, (a, b) => a.economy - b.economy),
  };
}

// ── Football: goals, assists, cards, clean sheets, Player of the Match and MVP points ──
// matches: [{ division_id, status, player_stats: [{id, name, team, goals, assists, yellow, red, clean_sheet, points}], potm: {id} }]
const POTM_POINTS = 3;
function computeFootballStats(matches) {
  const players = new Map();
  for (const m of matches) {
    const potm = m.status === 'COMPLETED' && m.potm ? m.potm.id : null;
    for (const r of m.player_stats || []) {
      const k = `${m.division_id}:${r.id}`;
      if (!players.has(k)) players.set(k, { division_id: m.division_id, member_id: r.id, name: r.name, entry_id: r.team,
        goals: 0, assists: 0, yellow: 0, red: 0, clean_sheets: 0, potm: 0, points: 0 });
      const p = players.get(k);
      p.goals += r.goals || 0; p.assists += r.assists || 0; p.yellow += r.yellow || 0; p.red += r.red || 0;
      p.clean_sheets += r.clean_sheet || 0; p.points += r.points || 0;
      if (potm === r.id) { p.potm++; p.points += POTM_POINTS; }
    }
  }
  return [...players.values()];
}

function footballLeaderboards(rows, top = 10) {
  const take = (filter, sort) => rows.filter(filter).sort(sort).slice(0, top);
  return {
    mvp: take(p => p.points > 0, (a, b) => b.points - a.points || b.goals - a.goals || b.potm - a.potm),
    top_scorers: take(p => p.goals > 0, (a, b) => b.goals - a.goals || b.assists - a.assists),
    most_assists: take(p => p.assists > 0, (a, b) => b.assists - a.assists || b.goals - a.goals),
    clean_sheets: take(p => p.clean_sheets > 0, (a, b) => b.clean_sheets - a.clean_sheets),
    player_of_match: take(p => p.potm > 0, (a, b) => b.potm - a.potm || b.points - a.points),
    yellow_cards: take(p => p.yellow > 0, (a, b) => b.yellow - a.yellow),
    red_cards: take(p => p.red > 0, (a, b) => b.red - a.red),
  };
}


const t = __$('Check Found').first().json;
const show = Number(t.is_owner) === 1 || Number(t.published) === 1;
const teams = (parseJ(t.teams) || []).map(x => ({ entry_id: x.entry_id, name: x.name, short: x.short, logo_url: signWith(x.logo_key, 'Team Link') }));
const matches = show ? (parseJ(t.matches) || []).map(m => ({ division_id: m.division_id, status: m.status, innings: parseJ(m.innings) || [],
  player_stats: parseJ(m.player_stats) || [], potm: parseJ(m.potm) })) : [];
const football = t.sport === 'FOOTBALL';
const rows = t.sport === 'CRICKET' ? computeStats(matches) : football ? computeFootballStats(matches) : [];

// ── Cricket Player of the Series: player-of-the-match points over the whole tournament ──
const fielding = new Map(); // `${division}:${member}` → { catches, run_outs }
{
  const byMatch = new Map();
  for (const e of parseJ(t.events) || []) { if (!byMatch.has(e.m)) byMatch.set(e.m, []); byMatch.get(e.m).push(e); }
  for (const evs of byMatch.values()) {
    const kept = [];
    for (const e of evs.sort((a, b) => a.s - b.s)) { if (e.type === 'UNDO') kept.pop(); else kept.push(e); }
    let bowler = null;
    for (const e of kept) {
      const data = parseJ(e.data) || {};
      if (e.type === 'START_INNINGS') bowler = data.bowler ?? null;
      if (e.type === 'NEW_BOWLER') bowler = data.id ?? null;
      const w = e.type === 'BALL' ? data.wicket : null;
      if (!w) continue;
      const fid = w.fielder ?? (w.how === 'CAUGHT' ? bowler : null);
      if (fid == null || !['CAUGHT', 'STUMPED', 'RUN_OUT'].includes(w.how)) continue;
      const k = `${e.d}:${fid}`;
      const f = fielding.get(k) || { catches: 0, run_outs: 0 };
      if (w.how === 'CAUGHT') f.catches++; else f.run_outs++;
      fielding.set(k, f);
    }
  }
}
const memberOf = new Map((parseJ(t.members) || []).map(m => [Number(m.id), m]));
function seriesOf(div, players, leaders, done) {
  const byId = new Map(players.map(p => [p.member_id, { ...p }]));
  for (const [k, f] of fielding) {
    const [d, id] = k.split(':').map(Number);
    if (d !== div || byId.has(id)) continue;
    const m = memberOf.get(id) || {};
    byId.set(id, { division_id: div, member_id: id, name: m.name || 'Player', entry_id: m.entry ?? null, runs: 0, wickets: 0 });
  }
  const plural = (n, w) => `${n} ${w}${n === 1 ? '' : w === 'catch' ? 'es' : 's'}`;
  const balls = players.reduce((s, p) => s + (p.legal_balls || 0), 0);
  const par = balls ? players.reduce((s, p) => s + (p.runs_conceded || 0), 0) / balls : 2;
  const rows = [...byId.values()].map(p => {
    const f = fielding.get(`${div}:${p.member_id}`) || { catches: 0, run_outs: 0 };
    // Formula E (as the app's Player of the Match), par = the division's runs per legal ball.
    const bat = p.innings ? (p.runs || 0) + 0.25 * ((p.runs || 0) - (p.balls || 0) * par) : 0;
    const bowl = 4 * (p.wickets || 0) + (p.legal_balls ? 0.75 * (p.legal_balls * par - (p.runs_conceded || 0)) : 0);
    const points = Math.round(bat + bowl + f.catches + f.run_outs);
    const reason = [p.innings && (p.runs || !p.wickets) ? `${p.runs} runs` : null, p.wickets ? plural(p.wickets, 'wicket') : null,
      f.catches ? plural(f.catches, 'catch') : null, f.run_outs ? plural(f.run_outs, 'run out') : null].filter(Boolean).join(' · ');
    return { member_id: p.member_id, name: p.name, entry_id: p.entry_id, runs: p.runs || 0, wickets: p.wickets || 0,
      catches: f.catches, run_outs: f.run_outs, points, reason };
  }).filter(p => p.points > 0).sort((a, b) => b.points - a.points || b.runs - a.runs || b.wickets - a.wickets);
  leaders.series_points = rows.slice(0, 10);
  return rows.length ? { ...rows[0], final: done } : null;
}
const divisions = (parseJ(t.divisions) || []).sort((a, b) => a.sort_order - b.sort_order).map(d => {
  const players = rows.filter(r => r.division_id === d.id);
  const leaders = football ? footballLeaderboards(players) : leaderboards(players);
  // Player of the Tournament: most MVP points; official once every match in the division is finished.
  const done = Number(d.total_matches) > 0 && Number(d.completed_matches) === Number(d.total_matches);
  const pott = football ? (leaders.mvp.length ? { ...leaders.mvp[0], final: done } : null) : seriesOf(d.id, players, leaders, done);
  return { id: d.id, name: d.name, matches: matches.filter(m => m.division_id === d.id).length, players, leaders, player_of_tournament: pott };
});
return [{ json: { status: 200, body: { success: true, sport: t.sport, teams, divisions, my_entry_ids: parseJ(t.my_entries) || [] } } }];

const out = JSON.parse(JSON.stringify($input.first().json));

// Children's names on public pages: first name + last initial ("Aarav Shah" → "Aarav S.").
const short = n => { const w = String(n || '').trim().split(/\s+/).filter(Boolean); return w.length < 2 ? (w[0] || '') : `${w[0]} ${w[w.length - 1][0].toUpperCase()}.`; };
if (out.status === 200 && out.body && out.body.success) {
  // The match endpoint wraps its data in body.match.
  const b = out.body.match || out.body;
  delete b.my_entry_ids;
  const clean = p => { if (p && typeof p === 'object') { p.name = short(p.name); delete p.photo_url; delete p.user_id; } return p; };
  for (const d of b.divisions || []) {
    (d.players || []).forEach(clean);
    for (const list of Object.values(d.leaders || {})) if (Array.isArray(list)) list.forEach(clean);
    if (d.player_of_tournament) clean(d.player_of_tournament);
  }
}

const cache = $getWorkflowStaticData('global');
const now = Date.now();
cache.c = Object.fromEntries(Object.entries(cache.c || {}).filter(([, v]) => now - v.at < 60000));
if (out.status === 200 && out.body && out.body.success) cache.c['s:' + String(($('Check Request').first().json._q || {}).slug || '')] = { at: now, body: out.body };
return [{ json: out }];

// The B2 links: saved ones while fresh, else the ones just fetched (saved for next time when all succeeded).
const store = $getWorkflowStaticData('global');
if ($('B2 Credentials').first().json.b2Fresh) return [{ json: { acct: store.b2.acct, links: store.b2.links } }];
const a = $('Authorize B2').first().json;
const acct = { apiInfo: a.apiInfo, authorizationToken: a.authorizationToken };
const links = {};
for (const n of ["Team Link"]) { try { const t = $(n).first().json.authorizationToken; if (t) links[n] = { authorizationToken: t }; } catch {} }
if (acct.authorizationToken && acct.apiInfo && Object.keys(links).length === 1) store.b2 = { at: Date.now(), acct, links };
return [{ json: { acct, links } }];
